BEGIN TRANSACTION;
PRAGMA defer_foreign_keys=ON;
CREATE TABLE specialized_supply_job (
                  job_id TEXT PRIMARY KEY,
                  child_id TEXT NOT NULL REFERENCES child_profile(child_id) ON DELETE CASCADE,
                  track TEXT NOT NULL,
                  subject TEXT NOT NULL,
                  domain_id TEXT NOT NULL,
                  seed_item_id TEXT NOT NULL REFERENCES diagnostic_item(diagnostic_item_id),
                  stages_json TEXT NOT NULL,
                  status TEXT NOT NULL CHECK(status IN ('pending','processing','completed','failed','blocked')),
                  attempt_count INTEGER NOT NULL DEFAULT 0,
                  error_code TEXT,
                  provider TEXT,
                  model TEXT,
                  prompt_tokens INTEGER,
                  completion_tokens INTEGER,
                  created_at TEXT NOT NULL,
                  updated_at TEXT NOT NULL,
                  client_action_id TEXT NOT NULL UNIQUE
                , generation_mode TEXT NOT NULL DEFAULT 'model', source_snapshot_json TEXT, retry_count INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_specialized_supply_job_status
                  ON specialized_supply_job(status, created_at);
CREATE TABLE specialized_supply_candidate (
                  candidate_id TEXT PRIMARY KEY,
                  job_id TEXT NOT NULL REFERENCES specialized_supply_job(job_id) ON DELETE CASCADE,
                  child_id TEXT NOT NULL REFERENCES child_profile(child_id) ON DELETE CASCADE,
                  track TEXT NOT NULL,
                  subject TEXT NOT NULL,
                  domain_id TEXT NOT NULL,
                  seed_item_id TEXT NOT NULL REFERENCES diagnostic_item(diagnostic_item_id),
                  stage TEXT NOT NULL,
                  prompt TEXT NOT NULL,
                  expected_answer_json TEXT NOT NULL,
                  explanation TEXT NOT NULL,
                  difficulty INTEGER NOT NULL,
                  content_fingerprint TEXT NOT NULL,
                  validation_json TEXT NOT NULL,
                  status TEXT NOT NULL CHECK(status IN ('needs_review','promoted','rejected')),
                  diagnostic_item_id TEXT REFERENCES diagnostic_item(diagnostic_item_id),
                  reviewed_at TEXT,
                  review_note TEXT,
                  review_action_id TEXT UNIQUE,
                  created_at TEXT NOT NULL,
                  UNIQUE(track, domain_id, content_fingerprint)
                );
CREATE INDEX idx_specialized_supply_review
                  ON specialized_supply_candidate(child_id, status, created_at);
CREATE TABLE curriculum_supply_selection(
                    selection_id TEXT PRIMARY KEY,
                    child_id TEXT NOT NULL REFERENCES child_profile(child_id) ON DELETE CASCADE,
                    subject TEXT NOT NULL, version INTEGER NOT NULL, scope_json TEXT NOT NULL,
                    actor TEXT NOT NULL, action_id TEXT NOT NULL, created_at TEXT NOT NULL,
                    UNIQUE(child_id,subject,version), UNIQUE(child_id,action_id));
CREATE TABLE curriculum_supply_package(
                    candidate_id TEXT PRIMARY KEY REFERENCES specialized_supply_candidate(candidate_id) ON DELETE CASCADE,
                    child_id TEXT NOT NULL REFERENCES child_profile(child_id) ON DELETE CASCADE,
                    author TEXT NOT NULL, payload_json TEXT NOT NULL, source_snapshot_json TEXT NOT NULL,
                    state TEXT NOT NULL, version INTEGER NOT NULL, supersedes TEXT,
                    blockers_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE curriculum_supply_event(
                    event_id TEXT PRIMARY KEY,
                    candidate_id TEXT NOT NULL REFERENCES curriculum_supply_package(candidate_id) ON DELETE CASCADE,
                    child_id TEXT NOT NULL REFERENCES child_profile(child_id) ON DELETE CASCADE,
                    version INTEGER NOT NULL, kind TEXT NOT NULL, actor TEXT NOT NULL,
                    action_id TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT NOT NULL,
                    created_at TEXT NOT NULL, UNIQUE(candidate_id,version), UNIQUE(child_id,action_id));
COMMIT;
