INSERT INTO "diagnostic_item" VALUES('diag-p4-arithmetic-closed-1','node-p4-math-arithmetic','计算 (24+6)×3，只回答一个整数。','text','{"keywords": ["90"], "local_rule": "local_exact_v1", "exact_answers": ["90"]}','先算括号内24+6=30，再算30×3=90。自编闭答案诊断。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-arithmetic-closed-2','node-p4-math-arithmetic','计算 24+6×3，只回答一个整数。','text','{"keywords": ["42"], "local_rule": "local_exact_v1", "exact_answers": ["42"]}','先算6×3=18，再算24+18=42。自编闭答案诊断。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-fraction-decimal-closed-1','node-p4-math-fractions-decimals','把3/10写成小数，只回答一个数。','text','{"keywords": ["0.3"], "local_rule": "local_exact_v1", "exact_answers": ["0.3"]}','3个十分之一写成0.3。自编闭答案诊断。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-fraction-decimal-closed-2','node-p4-math-fractions-decimals','计算2/10+5/10，把结果写成小数。','text','{"keywords": ["0.7"], "local_rule": "local_exact_v1", "exact_answers": ["0.7"]}','同分母相加得到7/10，写成小数是0.7。自编闭答案诊断。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-english-phonics-1','node-p4-english-phonics-discrimination','比较 cake、bag、name 中字母 a 的读音，哪一个不同？请说出判断依据。','text','{"keywords": ["bag", "不同", "cake", "name"]}','cake 和 name 中的字母 a 读音相同，bag 中的 a 读音不同，所以选择 bag。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-english-phonics-2','node-p4-english-phonics-discrimination','比较 bike、sit、five 中字母 i 的读音，哪一个不同？请说出判断依据。','text','{"keywords": ["sit", "不同", "bike", "five"]}','bike 和 five 中的字母 i 读音相同，sit 中的 i 读音不同，所以选择 sit。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-english-phonics-3','node-p4-english-phonics-discrimination','比较 home、hot、nose 中字母 o 的读音，哪一个不同？这次先按拼写分组，再逐词读音核对。','text','{"keywords": ["hot", "不同", "home", "nose"]}','home 和 nose 中的字母 o 读音相同，hot 中的 o 读音不同，所以选择 hot；最终判断必须来自实际读音对比。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-discriminant-1','node-j3-math-discriminant','方程 x²-4x+4=0 的判别式是多少？它有几个不同的实数根？','text','{"keywords": ["0", "一个", "1个", "两个相等"]}','判别式为16-16=0，因此有两个相等的实数根，也可说有一个不同的实数根。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-discriminant-2','node-j3-math-discriminant','不求解方程 2x²+x+3=0，判断它在实数范围内有没有解，并说明依据。','text','{"keywords": ["-23", "小于0", "没有实数", "无实数"]}','判别式1-24=-23，小于0，所以没有实数根。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-reading-1','node-j3-chinese-reading-evidence','阅读句子：‘雨停后，父亲没有立刻收伞，而是把伞向我这边又倾了倾。’这个细节主要表现了什么？请引用动作作为依据。','text','{"keywords": ["关爱", "照顾", "倾", "父亲"]}','‘把伞向我这边又倾了倾’这一动作表现父亲对孩子细致、无声的关爱。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-reading-2','node-j3-chinese-reading-evidence','阅读句子：‘奶奶把刚端上桌的鱼轻轻转了半圈，把鱼腹对着我。’这个动作表现了什么？请用句中细节作证。','text','{"keywords": ["关爱", "照顾", "鱼腹", "转"]}','‘把鱼腹对着我’的动作表现奶奶不声张地照顾孩子。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-reading-1','node-j3-english-reading-purpose','Read: ''The science club meeting has moved to Room 304 because the lab is being repaired. Please bring your project notes.'' What is the main purpose of the notice?','text','{"keywords": ["meeting", "Room 304", "moved", "bring"]}','The notice tells members about the new meeting room and reminds them what to bring.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-reading-2','node-j3-english-reading-purpose','Read: ''Library users: the second floor will close at 6 pm today for maintenance. Please return borrowed books at the desk downstairs.'' What is the notice asking readers to know or do?','text','{"keywords": ["second floor", "close", "6 pm", "return", "downstairs"]}','It announces the early closure of the second floor and tells users where to return books.',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-experiment-1','node-j3-physics-experiment-reasoning','探究滑动摩擦力与压力大小的关系时，为什么要让同一木块在同一水平面上运动？','text','{"keywords": ["控制", "接触面", "粗糙", "变量"]}','要控制接触面的粗糙程度等条件相同，只改变压力大小，才能判断压力对摩擦力的影响。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-experiment-2','node-j3-physics-experiment-reasoning','探究导体电阻与长度的关系时，为什么两根电阻丝应保持材料和横截面积相同？','text','{"keywords": ["控制变量", "材料", "横截面积", "长度"]}','要用控制变量法只改变长度，所以材料和横截面积必须相同。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-equation-1','node-j3-chem-equation','写出铁在氧气中燃烧生成四氧化三铁的化学方程式，并说明配平后的系数比。','text','{"keywords": ["3Fe", "2O2", "Fe3O4", "3:2:1"]}','3Fe+2O₂点燃生成Fe₃O₄，系数比为3:2:1。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-equation-2','node-j3-chem-equation','写出铝和氧气反应生成氧化铝的化学方程式，并说明配平后的系数比。','text','{"keywords": ["4Al", "3O2", "2Al2O3", "4:3:2"]}','4Al+3O₂生成2Al₂O₃，系数比为4:3:2。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-civics-material-1','node-j3-civics-material','同学未经允许把他人的照片做成表情包发到班群。请指出涉及的权利，并给出一条有依据的处理建议。','text','{"keywords": ["肖像", "隐私", "删除", "道歉"]}','可能涉及肖像权或隐私权；应停止传播、删除内容并向当事人道歉，必要时请老师和家长协助。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-civics-material-2','node-j3-civics-material','同学偷看别人的日记后把内容告诉多名同学。请指出可能被侵犯的权利，并给出两个合理的处理步骤。','text','{"keywords": ["隐私", "停止传播", "道歉", "老师"]}','这可能侵犯隐私权；应立即停止传播并道歉，必要时请老师或家长协助。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-causality-1','node-j3-history-causality','分析历史事件时，‘长期社会矛盾’和‘某次直接冲突’分别更接近背景原因还是直接原因？','text','{"keywords": ["背景", "长期", "直接", "冲突"]}','长期社会矛盾通常属于背景或根本原因，某次冲突通常属于直接原因或导火线。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-causality-2','node-j3-history-causality','一项改革前长期存在财政危机，后来因一次会议冲突而爆发。请区分财政危机和会议冲突的原因层次。','text','{"keywords": ["长期", "背景", "根本", "直接", "导火线"]}','长期财政危机是背景或根本原因，会议冲突是直接原因或导火线。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-1','node-pet-reading-main-idea','Read: ''Hi Sam, I left your blue notebook at the school office. You can collect it before 5 pm. Mia.'' Why did Mia write this message?','text','{"keywords": ["notebook", "office", "collect"]}','The message tells Sam where the notebook is and when to collect it.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-2','node-pet-reading-main-idea','Read: ''The swimming lesson will start at 4:30 instead of 4:00 today. Please wait by the small pool.'' What is the main purpose of this notice?','text','{"keywords": ["time", "4:30", "change", "pool"]}','It tells learners about a changed start time and where to wait.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-pattern-1','node-oly-pattern','观察 2, 5, 10, 17, 26。下一个数是多少？请说明规律。','text','{"keywords": ["37", "加3", "加5", "加7", "加9", "奇数"]}','相邻两项依次加3、5、7、9，所以下一次加11，得到37。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-pattern-2','node-oly-pattern','一排图形所用小棒数是4、7、10、13……第8个图形需要多少根？请说明你怎样从规律得到。','text','{"keywords": ["25", "每次多3", "加3", "4+7×3"]}','每增加一个图形多3根，第8个需要4+7×3=25根。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-counting-1','node-oly-counting','用数字1、2、3组成没有重复数字的两位数，一共有多少个？请有序列出。','text','{"keywords": ["6", "12", "13", "21", "23", "31", "32"]}','十位有3种选择，个位剩2种，共6个：12、13、21、23、31、32。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-counting-2','node-oly-counting','小明从A到B可选2条路，从B到C可选3条路。必须经过B，从A到C共有几种不同走法？请解释为什么。','text','{"keywords": ["6", "2×3", "2*3", "每条", "搭配"]}','A到B的每种走法都能搭配3种B到C走法，所以2×3=6种。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-pattern-3','node-oly-pattern','把1、4、9、16继续写两项，并说明这些数与图形有什么关系。','text','{"keywords": ["25", "36", "平方", "正方形"]}','它们是1²、2²、3²、4²，后两项是25和36，可看作边长递增的正方形点阵。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-counting-3','node-oly-counting','书架上有3本不同的故事书和2本不同的科普书，各选一本共有多少种选法？请说明怎样保证不遗漏。','text','{"keywords": ["6", "3×2", "3*2", "列表", "搭配"]}','每本故事书都可搭配2本科普书，共3×2=6种；可用表格逐行列出。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-area-1','node-oly-area','一个10厘米×8厘米的长方形右上角剪去一个4厘米×3厘米的小长方形，剩余面积是多少？','text','{"keywords": ["68", "80", "12", "减"]}','先算整体80平方厘米，再减去12平方厘米，剩68平方厘米。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-area-2','node-oly-area','一个长方形面积是48平方厘米，长是8厘米。把它平均分成两个相同小长方形，每个小长方形面积是多少？说明是否需要先求宽。','text','{"keywords": ["24", "不需要", "一半"]}','平均分成两个相同部分，每部分面积就是48÷2=24平方厘米，不必先求宽。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-number-sense-1','node-oly-number-sense','从1写到100，数字9一共出现多少次？请分个位和十位说明。','text','{"keywords": ["20", "个位", "十位", "10"]}','个位出现10次，十位出现10次，共20次；99中的两个9分别计数。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-number-sense-2','node-oly-number-sense','不精确计算，估计398×51更接近2000、20000还是200000，并说明理由。','text','{"keywords": ["20000", "400", "50"]}','把398看作400、51看作50，400×50=20000。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-arithmetic-1','node-oly-arithmetic-structure','不用竖式，计算125×32，并写出你的巧算过程。','text','{"keywords": ["4000", "125×8", "125*8", "32=8×4", "乘4"]}','把32拆成8×4，125×8×4=1000×4=4000。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-arithmetic-2','node-oly-arithmetic-structure','用简便方法计算99×37，并说明用了什么结构。','text','{"keywords": ["3663", "100×37", "3700", "减37", "分配律"]}','99×37=(100-1)×37=3700-37=3663，使用分配律。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-number-theory-1','node-oly-number-theory','36有多少个正因数？请成对列出。','text','{"keywords": ["9", "1和36", "2和18", "3和12", "4和9", "6和6"]}','因数对为1和36、2和18、3和12、4和9、6和6，共9个不同正因数。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-number-theory-2','node-oly-number-theory','一个三位数4□2能被3整除，方框里可以填哪些数字？说明依据。','text','{"keywords": ["0", "3", "6", "9", "各位数字和", "被3整除"]}','各位数字和6+□应是3的倍数，所以可填0、3、6、9。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-logic-1','node-oly-logic','甲、乙、丙比赛跑步。甲不是第一，乙在丙前面，丙不是第二。三人的名次分别是什么？','text','{"keywords": ["乙第一", "甲第二", "丙第三"]}','乙必须在丙前；丙不是第二只能第三，乙第一，甲第二。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-logic-2','node-oly-logic','三个盒子分别标着苹果、梨、混合，但三个标签全错。只从一个盒子拿一个水果，应该先从哪个标签的盒子拿？为什么？','text','{"keywords": ["混合", "标签全错", "实际不是混合"]}','先从标着“混合”的盒子拿，因为它实际一定不是混合；拿到的水果可确定该盒内容，再推出另外两个。',NULL,NULL,'objective',3,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-modeling-1','node-oly-modeling','停车场有自行车和三轮车共10辆，共有24个轮子。两种车各多少辆？请用一种表示方法说明。','text','{"keywords": ["6辆自行车", "4辆三轮车", "自行车6", "三轮车4", "假设"]}','若全是自行车有20个轮子，多出的4个轮子说明有4辆三轮车，所以自行车6辆。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-modeling-2','node-oly-modeling','成人票每张20元，儿童票每张12元。2名成人和3名儿童一共多少钱？先写数量关系再计算。','text','{"keywords": ["76", "2×20", "3×12", "相加"]}','总价=成人票价×人数+儿童票价×人数=2×20+3×12=76元。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-expression-1','node-oly-expression','计算(36+24)÷6×5，并用一句话说明运算顺序。','text','{"keywords": ["50", "先算括号", "从左到右"]}','先算括号得60，再按从左到右计算60÷6×5=50。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-expression-2','node-oly-expression','小华有40元，买3本每本8元的本子。请只列一个综合算式表示剩下的钱，并解释每一部分。','text','{"keywords": ["40-3×8", "40-8×3", "16", "总钱数", "总价"]}','综合算式40-3×8=16元；3×8是本子总价，再从40元中减去。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-detail-baseline','node-pet-reading-detail','Read: ''The art club meets on Tuesday in Room 6. Bring a pencil and an old shirt.'' When and where does the club meet?','text','{"keywords": ["Tuesday", "Room 6"]}','It meets on Tuesday in Room 6.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-vocabulary-baseline','node-pet-reading-vocabulary','Read: ''The path was narrow, so only one person could walk on it at a time.'' What does narrow mean here?','text','{"keywords": ["not wide", "small width", "only one"]}','Narrow means not wide.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-inference-baseline','node-pet-reading-inference','Read: ''Nina closed the window, put on her coat and took an umbrella.'' What was the weather probably like? Give one clue.','text','{"keywords": ["rain", "cold", "umbrella", "coat"]}','It was probably rainy or cold; the umbrella or coat is the clue.',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-reading-text-function-baseline','node-pet-reading-text-function','Read: ''Please do not leave bicycles outside this door. Use the racks beside the library.'' Why is this notice here?','text','{"keywords": ["tell", "ask", "bicycles", "racks"]}','It tells cyclists where they should leave their bicycles.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-listening-gist-baseline','node-pet-listening-gist','Listen: ''I planned to play tennis, but the court is wet. Let''s go to the sports centre and swim instead.'' What will the speakers do?','text','{"keywords": ["swim", "sports centre"]}','They will swim at the sports centre.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-listening-intent-baseline','node-pet-listening-intent','Listen: ''Could you turn the music down? I am trying to finish my homework.'' What does the speaker want?','text','{"keywords": ["music", "down", "quieter"]}','The speaker wants the music to be quieter.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-listening-note-baseline','node-pet-listening-note','Listen: ''The class trip leaves school at eight fifteen on Friday. Meet by the main gate and bring a bottle of water.'' Say the time, meeting place and one thing to bring.','text','{"keywords": ["8:15", "eight fifteen", "main gate", "water"]}','The time is 8:15, the place is the main gate, and students need water.',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-writing-organization-baseline','node-pet-writing-organization','Write 35-55 words to tell a friend about a school activity. Include when it happened, what you did, and how you felt. Use at least two linking words.','writing','{"task_points": ["时间", "活动", "感受", "连接"], "keyword_groups": [["yesterday", "last", "on monday", "week"], ["did", "played", "made", "visited", "joined"], ["felt", "happy", "excited", "tired", "enjoyed"], ["and", "but", "because", "then", "so"]], "min_words": 35, "max_words": 55}','参考量表检查信息顺序和衔接，不等同于PET官方评分。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-writing-grammar-baseline','node-pet-writing-grammar','Write 35-55 words about what you did last Sunday and what you will do next Sunday. Give a reason for one activity.','writing','{"task_points": ["过去活动", "未来活动", "原因"], "keyword_groups": [["went", "played", "visited", "watched", "did"], ["will", "going to"], ["because", "so"]], "min_words": 35, "max_words": 55}','参考量表检查过去与未来表达及完整句，不等同于PET官方评分。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-writing-vocabulary-baseline','node-pet-writing-vocabulary','Write 35-55 words describing a place you enjoy. Include two details about the place, one activity, and why you like it.','writing','{"task_points": ["地点细节", "活动", "原因"], "keyword_groups": [["big", "small", "quiet", "bright", "beautiful", "near", "trees"], ["read", "play", "walk", "study", "meet"], ["because", "so", "like", "enjoy"]], "min_words": 35, "max_words": 55}','参考量表检查具体词语和任务完成，不等同于PET官方评分。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-speaking-interaction-baseline','node-pet-speaking-interaction','Let''s plan a class picnic. Suggest a place and time, say what to bring, then ask me one question.','speaking','{"task_points": ["地点时间", "携带物品", "追问"], "keyword_groups": [["park", "school", "saturday", "sunday", "morning", "afternoon"], ["bring", "food", "water", "ball", "blanket"], ["what", "where", "when", "shall", "do you"]], "min_words": 18}','参考量表只根据转写检查互动任务点，不能判断发音。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-speaking-extended-baseline','node-pet-speaking-extended','Talk for about half a minute about a skill you want to learn. Say what it is, why, how you can practise, and who can help.','speaking','{"task_points": ["技能", "原因", "练习", "帮助者"], "keyword_groups": [["learn", "want", "skill"], ["because"], ["practise", "practice", "every day", "week"], ["teacher", "friend", "parent", "mother", "father"]], "min_words": 28}','参考量表只根据转写检查连续表达内容，不能判断发音或真实流利度。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-oly-transfer-baseline','node-oly-transfer','一辆车每次能运4箱书，运完22箱至少要几次？如果把书换成每盒装4个球、共有22个球，方法哪里相同？','text','{"keywords": ["6", "除以4", "向上取整", "余数", "相同"]}','22除以4等于5余2，所以至少6次；两个情境都要把有余数的结果向上取整。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-literature-baseline','node-j3-chinese-literature','句子‘老屋的灯在风里一闪一闪，却始终没有熄灭’既写景又有何表达作用？请结合‘始终没有熄灭’说明。','text','{"keywords": ["象征", "希望", "坚持", "坚守", "始终"]}','‘始终没有熄灭’突出坚守，可象征人物未放弃的希望或信念。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-classics-baseline','node-j3-chinese-classics','‘虽有嘉肴，弗食，不知其旨也’中的‘旨’是什么意思？这句话说明了什么道理？','text','{"keywords": ["味美", "美味", "实践", "亲自", "学习"]}','‘旨’是味美；只拥有好东西却不亲自品尝就不知道滋味，强调亲身学习实践。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-language-baseline','node-j3-chinese-language','你要在班级群提醒同学明早交社会实践表。请写一句信息完整、语气得体的通知。','text','{"keywords": ["同学", "明早", "实践表", "请", "谢谢"]}','示例：请同学们明早到校后把社会实践表交给组长，谢谢大家配合。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chinese-writing-baseline','node-j3-chinese-writing','以‘那一步，我终于迈了出去’为题，口述中心立意、开头事件、转折和结尾照应，各用一句话。','text','{"keywords": ["立意", "开头", "转折", "结尾", "照应"]}','答案应形成中心明确、事件推进、有转折且结尾照应题目的提纲。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-math-number-expression-baseline','node-j3-math-number-expression','化简 (a²-4)/(a-2)，并说明原式中a不能取什么值。','text','{"keywords": ["a+2", "a不能等于2", "a≠2", "2"]}','因式分解为(a-2)(a+2)，约分得a+2，但原式要求a不等于2。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-math-function-baseline','node-j3-math-function','一次函数 y=-2x+5 中，y随x增大怎样变化？图像与y轴交点是多少？','text','{"keywords": ["减小", "0,5", "(0,5)", "5"]}','斜率-2小于0，所以y随x增大而减小；与y轴交于(0,5)。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-math-geometry-proof-baseline','node-j3-math-geometry-proof','在等腰三角形ABC中，AB=AC，AD平分∠A并交BC于D。要证明BD=CD，可用哪两个三角形全等？列出三个条件。','text','{"keywords": ["ABD", "ACD", "AB=AC", "AD", "角BAD", "角CAD", "SAS"]}','证明△ABD与△ACD全等：AB=AC，AD公共，∠BAD=∠CAD，用SAS得BD=CD。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-math-statistics-baseline','node-j3-math-statistics','袋中有3个红球和2个蓝球，除颜色外相同。随机摸1个球，摸到红球的概率是多少？','text','{"keywords": ["3/5", "五分之三", "0.6"]}','共有5个等可能球，其中3个红球，概率为3/5。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-math-modeling-baseline','node-j3-math-modeling','某商品原价100元，连续两次按相同折扣率降价后为81元。设每次降价率为x，只列方程并说明x的取值范围。','text','{"keywords": ["100(1-x)²=81", "100(1-x)^2=81", "0<x<1", "0≤x≤1"]}','方程为100(1-x)²=81，降价率应在0到1之间。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-listening-baseline','node-j3-english-listening','Listen to the original recording. When and where should they meet?','listening_text','{"keywords": ["7:30", "seven thirty", "school gate"]}','They should meet at 7:30 beside the school gate.','The bus leaves at 7:40, but we should meet ten minutes earlier beside the school gate.',NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-grammar-baseline','node-j3-english-grammar','Complete: If it ___ tomorrow, we will move the sports meeting indoors. Use the correct form of ''rain''.','text','{"keywords": ["rains"]}','Use rains: the if-clause uses the present simple for a real future condition.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-task-reading-baseline','node-j3-english-task-reading','Read: ''The museum opens at 9:00. Student tickets cost 20 yuan. Photography is allowed without flash.'' Give the opening time, student price and photography rule.','text','{"keywords": ["9:00", "20", "without flash", "no flash"]}','It opens at 9:00, costs students 20 yuan, and permits photography without flash.',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-english-writing-baseline','node-j3-english-writing','Write at least 60 words proposing one way to make your school greener. Explain the problem, action and expected result.','writing','{"task_points": ["问题", "行动", "结果"], "keyword_groups": [["problem", "waste", "plastic", "energy", "water"], ["should", "can", "plan", "organize", "reduce", "reuse"], ["result", "so", "therefore", "cleaner", "greener", "save"]], "min_words": 60}','参考量表检查问题、行动、结果和基本连贯性，不代替学校正式评分。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-motion-baseline','node-j3-physics-motion','汽车匀速直线行驶时，水平方向牵引力与阻力是什么关系？为什么？','text','{"keywords": ["相等", "平衡", "合力为0", "匀速"]}','匀速直线运动时合力为0，所以牵引力与阻力大小相等、方向相反。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-density-baseline','node-j3-physics-density','一个物体完全浸没在水中，排开水的体积为0.002立方米。取水的密度1000千克每立方米、g=10，浮力是多少？','text','{"keywords": ["20N", "20牛", "20"]}','浮力等于ρgV=1000×10×0.002=20N。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-energy-baseline','node-j3-physics-energy','用50牛的力把物体沿力的方向移动4米，用时10秒。做功和功率各是多少？','text','{"keywords": ["200J", "200焦", "20W", "20瓦"]}','功W=Fs=200J，功率P=W/t=20W。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-physics-electricity-baseline','node-j3-physics-electricity','一个6欧电阻两端电压为12伏，通过它的电流是多少？若电压不变，电阻增大，电流怎样变化？','text','{"keywords": ["2A", "2安", "减小"]}','I=U/R=12/6=2A；电压不变时电阻增大，电流减小。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-particles-baseline','node-j3-chem-particles','水蒸发成为水蒸气时，水分子的种类和分子间隔分别怎样变化？','text','{"keywords": ["种类不变", "没有变", "间隔变大"]}','物理变化中水分子种类不变，分子间隔变大。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-symbols-baseline','node-j3-chem-symbols','用化学用语表示：两个氧原子、一个氧分子、一个带两个单位正电荷的镁离子。','text','{"keywords": ["2O", "O2", "Mg2+", "Mg²+"]}','依次为2O、O₂、Mg²⁺。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-substances-baseline','node-j3-chem-substances','实验室检验二氧化碳常把气体通入什么液体？出现什么现象？','text','{"keywords": ["澄清石灰水", "石灰水", "浑浊"]}','通入澄清石灰水，石灰水变浑浊。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-chem-experiment-baseline','node-j3-chem-experiment','10克碳酸钙充分反应后理论上生成4.4克二氧化碳。若实际收集3.96克，收集率是多少？','text','{"keywords": ["90%", "百分之九十", "0.9"]}','收集率=3.96÷4.4×100%=90%。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-civics-concepts-baseline','node-j3-civics-concepts','为什么公民享有权利的同时也必须履行义务？请说明权利与义务的关系。','text','{"keywords": ["统一", "相互依存", "相互促进", "既是权利", "也是义务"]}','权利与义务相统一、相互依存相互促进，公民既是权利主体也是义务主体。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-civics-argument-baseline','node-j3-civics-argument','有人说‘网络发言是我的自由，想说什么都可以’。请用权利边界的观点作出判断并说明理由。','text','{"keywords": ["错误", "边界", "法律", "他人权利", "义务"]}','观点错误；自由有法律和他人权利的边界，行使权利不能损害国家、社会和他人合法权益。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-civics-practice-baseline','node-j3-civics-practice','发现社区无障碍通道常被车辆占用，作为中学生可以采取哪两个合法、可行的行动？','text','{"keywords": ["劝阻", "物业", "社区", "反映", "建议", "证据"]}','可礼貌劝阻或记录情况，向物业、社区等反映并提出规范停车建议，不能采取过激行为。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-timeline-baseline','node-j3-history-timeline','请按时间先后排列：鸦片战争、辛亥革命、五四运动，并写出最早事件的大致年代。','text','{"keywords": ["鸦片战争", "辛亥革命", "五四运动", "1840"]}','顺序是鸦片战争、辛亥革命、五四运动；鸦片战争开始于1840年。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-facts-baseline','node-j3-history-facts','辛亥革命在政治制度方面最重要的直接成果是什么？','text','{"keywords": ["清朝", "君主专制", "共和", "中华民国"]}','辛亥革命推翻清朝统治，结束君主专制制度，建立中华民国。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-source-baseline','node-j3-history-source','一份工厂记录显示某年女工人数明显增加。仅凭这条材料，能否直接断言所有女性社会地位都提高了？为什么？','text','{"keywords": ["不能", "证据不足", "局限", "一份", "所有"]}','不能；单一工厂记录只能说明局部就业变化，不能直接概括所有女性的社会地位。',NULL,NULL,'objective',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-j3-history-compare-baseline','node-j3-history-compare','比较两次改革时，为什么要先确定同一个比较维度？请举一个可用维度。','text','{"keywords": ["可比", "同一", "背景", "内容", "影响", "结果"]}','同一维度才能避免把不同层面混在一起；可比较背景、措施、结果或影响。',NULL,NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-listening-1','node-pet-listening-detail','听两遍短消息：Where should Leo meet Anna?','listening_text','{"keywords": ["library", "front", "门口"]}','Leo should meet Anna in front of the library at half past three.','Hi Leo. The football practice is cancelled today. Please meet me in front of the library at half past three. Anna.',NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-listening-2','node-pet-listening-detail','听两遍通知：What must students bring?','listening_text','{"keywords": ["raincoat", "雨衣"]}','Students must bring a raincoat because the walk will continue if it rains.','Tomorrow''s nature walk starts at nine. Bring a raincoat because we will still go if it rains. You do not need to bring lunch.',NULL,'objective',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-writing-1','node-pet-writing-email','Write an email to your English friend Alex. Invite Alex to study with you this Saturday. Say where to meet, what time, and what you will study. Write about 35-55 words.','writing','{"task_points": ["地点", "时间", "学习内容"], "keyword_groups": [["library", "home", "school", "cafe", "park"], ["am", "pm", "o''clock", "morning", "afternoon"], ["math", "english", "science", "homework", "study"]], "min_words": 35, "max_words": 55}','参考量表看任务点覆盖、基本连贯和可理解语言，不等同于PET官方评分。',NULL,NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-writing-2','node-pet-writing-email','Write a short email to Mia. Thank her for a book, say what you liked about it, and tell her when you will return it. Write about 35-55 words.','writing','{"task_points": ["感谢", "喜欢之处", "归还时间"], "keyword_groups": [["thank"], ["like", "liked", "interesting", "funny", "exciting"], ["return", "give back", "tomorrow", "monday", "week"]], "min_words": 35, "max_words": 55}','参考量表看三个任务点、组织和可理解性，不等同于PET官方评分。',NULL,NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-speaking-1','node-pet-speaking-picture','Look at the study-room picture and describe what the people are doing. Then make one guess about what may happen next.','speaking','{"task_points": ["人物", "动作", "推测"], "keyword_groups": [["boy", "girl", "child", "student", "people"], ["reading", "writing", "studying", "talking", "looking"], ["maybe", "might", "will", "probably", "next"]], "min_words": 20}','参考量表仅根据本地转写评估任务完成和表达展开，不能据此判断发音。',NULL,'pet-study-room','pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-speaking-2','node-pet-speaking-picture','Talk about a place where you like to read. Say where it is, what you read there, and why you like it.','speaking','{"task_points": ["地点", "阅读内容", "原因"], "keyword_groups": [["home", "room", "library", "school", "cafe", "park"], ["book", "story", "novel", "comic", "magazine"], ["because", "quiet", "comfortable", "interesting", "relax"]], "min_words": 20}','参考量表仅根据本地转写评估内容覆盖和连贯性，不能据此判断发音。',NULL,NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-read-aloud-1','node-pet-speaking-read-aloud','请先默读下面的短文，再用自然速度完整朗读。系统只检查本地转写是否覆盖文本，不评判发音。','read_aloud','{"task_points": ["开头信息", "中间行动", "结尾目的"], "keyword_groups": [["saturday", "morning", "ben"], ["market", "father", "apples", "bread"], ["picnic", "park"]], "min_words": 20}','参考量表只检查转写中的段落覆盖，不能判断发音、重音、语调或流利度。','On Saturday morning, Ben walks to the market with his father. They buy apples and bread because the family is having a picnic in the park.',NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-daily-dialogue-1','node-pet-function-communication','I ask: ''Would you like to study together this Saturday?'' Reply in English. Say yes or no, suggest a time and place, say what to study, and ask me one question.','speaking','{"task_points": ["回应邀请", "时间地点", "学习内容", "反问"], "keyword_groups": [["yes", "sure", "sorry", "can", "would"], ["saturday", "morning", "afternoon", "library", "home", "school"], ["study", "english", "math", "homework", "science"], ["what", "where", "when", "do you", "shall we"]], "min_words": 20}','参考量表只根据本地转写检查交际任务点，不能判断发音或真实对话流利度。',NULL,NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-daily-story-create-1','node-pet-grammar-sentence','Continue this story in 35-55 words: ''Mia opened her school bag and found a tiny map inside. The map showed a red star near the old library...'' Include an action, a small problem, and an ending.','writing','{"task_points": ["行动", "问题", "结尾"], "keyword_groups": [["went", "walked", "looked", "opened", "found", "followed"], ["but", "problem", "lost", "couldn''t", "could not", "wrong"], ["finally", "at last", "in the end", "home", "safe", "found"]], "min_words": 35, "max_words": 55}','参考量表检查故事任务点、基本连贯和可理解语言，不等同于PET官方评分。',NULL,NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-pet-daily-retell-1','node-pet-reading-main-idea','Read or listen to the short story, then retell it in English. Say who was there, what happened, and how it ended.','speaking','{"task_points": ["人物", "经过", "结果"], "keyword_groups": [["lily", "girl"], ["dog", "library", "water", "owner", "called"], ["home", "safe", "finally", "owner came"]], "min_words": 20}','参考量表只根据本地转写检查复述内容覆盖，不能判断发音。','Lily found a small dog near the library. The dog looked tired, so she gave it some water. She called the phone number on its collar. Soon the owner came, and the dog went home safely.',NULL,'pet_reference_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-open-math-reasoning-1','node-p4-open-math-reasoning','每盒彩笔12支，买3盒后平均分给6人。小林列式12×3÷6。解释每一步表示什么，并检查结果是否合理。','open_response','{"task_points": ["说明先求总数再平均分的依据", "用原题条件检查结果"], "review_profile": "school_p4_open_math_mathematical_process_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "mathematical_process", "response_mode": "written", "context_requirement": "self_contained"}','自编原题参考；原始作答仍须逐项可靠评分，不能据此自动认证掌握。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-open-chinese-reading-1','node-p4-open-chinese-reading','读短文：小禾走到门口，看见雨水打湿了台阶。她返回屋里拿了伞，又把门边的小凳子搬进屋。小禾为什么返回屋里？请结合原文说明，不把猜测当作事实。','open_response','{"task_points": ["回答小禾返回屋里的原因", "结合原文具体信息说明依据"], "review_profile": "school_p4_open_chinese_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "written", "context_requirement": "self_contained"}','自编原题参考；原始作答仍须逐项可靠评分，不能据此自动认证掌握。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-open-chinese-writing-1','node-p4-open-chinese-writing','给一位没参加班级活动的同学写一段话，介绍一次你熟悉的活动。写清发生了什么，选择一个具体细节，并说说你的感受。','open_response','{"task_points": ["写清活动和事情经过", "选择具体细节并表达感受"], "review_profile": "school_p4_open_chinese_communicative_writing_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "communicative_writing", "response_mode": "written", "context_requirement": "self_contained"}','自编原题参考；原始作答仍须逐项可靠评分，不能据此自动认证掌握。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-p4-open-english-reading-1','node-p4-open-english-reading','Read: Lily has a new book. She puts it in her bag and walks to Ben''s home. Ben wants to read it too. Why does Lily take the book? Use information from the text to explain.','open_response','{"task_points": ["回答Lily带书的原因", "使用短文信息支持解释"], "review_profile": "school_p4_open_english_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "written", "context_requirement": "self_contained"}','自编原题参考；原始作答仍须逐项可靠评分，不能据此自动认证掌握。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-math-roots','node-j3-math-discriminant','小林认为方程 x²-6x+5=0 有两个相等的实数根，因为一次项系数是偶数。请口头判断他的说法，说明如何检验；不必求出两个根。','open_response','{"task_points": ["识别a=1、b=-6、c=5，不能用一次项奇偶性判断根。", "计算b²-4ac=36-20=16。", "由判别式大于0推出两个不相等实数根，并指出原判断错误。"], "review_profile": "school_open_math_mathematical_process_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "mathematical_process", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先问“根的个数与哪个量的符号有关”，再请孩子自己代入。判别式16大于0，有两个不相等实数根。偶数一次项不是判据。若孩子只说有两个根，追问相等与否及依据；不给出结论后立即让孩子复述来充当独立检查。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-math-parameter','node-j3-math-discriminant','方程 x²+2x+k=0 有实数根。小夏说“k只能等于1”。请说明k的范围，并解释边界值与范围内其他值的区别。','open_response','{"task_points": ["判别式为4-4k，存在实数根要求其大于或等于0。", "解得k小于或等于1，不是只取1。", "k=1为两个相等实数根，k<1为两个不相等实数根。"], "review_profile": "school_open_math_mathematical_process_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "mathematical_process", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','从“有实数根”翻译成判别式非负，而不是判别式等于零。4-4k≥0得到k≤1。分别讨论等号与严格小于；可追问k=0是否满足以检验“只能等于1”的说法。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-chinese-action','node-j3-chinese-reading-evidence','读自编短文：“我把落选的通知揉成一团。哥哥没有问名次，只把我散在地上的设计图逐张摊平，说：周末再试试这座桥怎么搭。”哥哥的做法怎样回应了“我”的处境？请结合两个具体细节说明，不补写人物经历。','open_response','{"task_points": ["从揉通知识别失落或受挫处境，不捏造其他经历。", "结合没有问名次、逐张摊平设计图、邀请再试等至少两个细节。", "说明行动如何传达理解、尊重努力或鼓励继续实践，允许有文本支持的不同表达。"], "review_profile": "school_open_chinese_textual_interpretation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先让孩子指出文本里实际发生的动作，再把“没有追问名次”和“整理图纸、邀请再试”与失落联系。可以理解为不以结果责备、仍重视努力并提供支持。仅答“哥哥很好”缺少依据；不能把答案限制成必须出现某几个词。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-chinese-evidence','node-j3-chinese-reading-evidence','读自编短文：“志愿者说，只要把修好的旧书送回流动书架，就能让它再陪一个读者。我原想买新书，听完便取出胶带，把脱落的书页一页页贴好。”有人概括为“我再也不买新书了”。这个概括是否得到原文支持？请给出更准确的概括和依据。','open_response','{"task_points": ["指出再也不买新书扩大了原文信息。", "引用听完后取胶带修书的转变，区分本次行为与永久决定。", "概括对修复再利用或共享价值的理解及行动，不强求唯一措辞。"], "review_profile": "school_open_chinese_textual_interpretation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','比较“这一次做了什么”和“以后永远怎样”。文本只表明受到提醒后开始修书、使旧书继续被利用，没有永不买书的证据。请孩子删除概括中无法在文中找到支持的词。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-english-purpose','node-j3-english-reading-purpose','Read this original notice: "Garden volunteers: Saturday''s planting will begin at 10, not 9, because the soil delivery is late. Wear old shoes. We will provide gloves." Explain the purpose of the notice and distinguish what volunteers should bring from what is provided.','open_response','{"task_points": ["说明通知更改种植活动开始时间并交代准备事项。", "新时间10点而非9点；迟到的是泥土配送，不据此推断活动取消。", "穿旧鞋，手套由组织方提供；以原文为据，允许用自己的话解释。"], "review_profile": "school_open_english_textual_interpretation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','Ask what changed, what the reader must do, and what the organiser provides. Planting still happens, at 10. Volunteers wear old shoes; they need not infer that gloves must be brought. Check understanding separately from small language errors.',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-english-limit','node-j3-english-reading-purpose','Read this original message: "To visitors: The east entrance is closed until Friday. Please use the west gate. Wheelchair users can ask the office for help with the temporary ramp." Does this mean the whole building is closed? Explain the message and what two groups of visitors can do.','open_response','{"task_points": ["区分关闭东入口与关闭整栋楼，否定无根据的扩大解释。", "一般访客使用西门。", "轮椅使用者可向办公室寻求临时坡道帮助，引用相关信息而不编造开放时间。"], "review_profile": "school_open_english_textual_interpretation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','Locate the exact noun modified by closed: the east entrance. The instruction to use the west gate supports continued access. Separate the general direction from the optional accessibility assistance; do not infer that every visitor must report to the office.',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-physics-confound','node-j3-physics-experiment-reasoning','两根镍铬合金丝温度相同：甲长20厘米、横截面积0.2平方毫米，乙长40厘米、横截面积0.4平方毫米。小宁想只比较电阻与长度的关系。这组选材能直接检验吗？请说明问题，并描述应怎样更换乙来控制变量。','open_response','{"task_points": ["长度与横截面积同时改变，不能把结果单独归因于长度。", "乙应与甲材料、横截面积及温度相同，长度不同。", "说明测量比较电阻而非仅凭长度猜结论，不编造实测数据。"], "review_profile": "school_open_physics_scientific_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "scientific_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','请孩子逐项列出甲乙的共同点和不同点。这里有两个变量同时变化。可把乙换成同材料、同温度、截面积0.2平方毫米而长度40厘米的合金丝，再测电阻。不能从这道选材题编出实验已证明的结论。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-physics-data','node-j3-physics-experiment-reasoning','一次控制材料、横截面积和温度相同的导线实验记录为：长度10厘米时电阻2欧，20厘米时4欧，30厘米时6欧。请概括记录支持的关系，并评价“任何导线只要长30厘米，电阻就一定是6欧”这句话。','open_response','{"task_points": ["在本实验控制条件下，给定三组数据电阻随长度成正比。", "用两组或比值作为依据，如长度倍增时电阻倍增。", "结论受材料、横截面积和温度等条件限制，不能推广到任意导线。"], "review_profile": "school_open_physics_scientific_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "scientific_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先比较长度和电阻的倍数或R/L，再强调相同的控制条件。三组记录支持本条件下的比例关系；另一种材料或另一截面积的导线可能不是6欧。观察到的规律与无条件断言要分开。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-chem-methane','node-j3-chem-equation','题给反应事实：甲烷CH₄在足量氧气中点燃，生成CO₂和H₂O。请口头说出配平后的化学方程式、各物质系数比，并按元素核对原子数。这里只讨论题给反应，不进行实验。','open_response','{"task_points": ["依据题给产物写出CH₄+2O₂→CO₂+2H₂O，说明点燃条件。", "系数比1:2:1:2；不通过改变化学式下标配平。", "左右C各1、H各4、O各4，说明原子守恒。"], "review_profile": "school_open_chemistry_scientific_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "scientific_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先定化学式，再看碳、氢，最后数氧。一个CH₄对应一个CO₂和两个H₂O，右侧共4个氧，故左侧2O₂。用元素逐项核对解释配平，而不是只背系数。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-chem-aluminium','node-j3-chem-equation','已知铝Al在氧气O₂中点燃生成氧化铝Al₂O₃。小冬为配平把产物改写成AlO。为什么不可以？请给出正确的系数比，并核对两种元素。这里只做纸面分析。','open_response','{"task_points": ["产物化学式由反应事实决定，不能为配平更改为AlO。", "正确方程式4Al+3O₂→2Al₂O₃并保留点燃条件，系数比4:3:2。", "两侧Al各4、O各6，区分系数与下标。"], "review_profile": "school_open_chemistry_scientific_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "scientific_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','追问“改变下标后还是题给的物质吗”。氧原子取2与3的公倍数6，得到3O₂与2Al₂O₃，再补4Al。配平只调整系数，不改变物质身份。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-civics-procedure','node-j3-civics-material','自编班级协商材料：班级约定活动方案须先征求每组意见，再表决。组长没询问两名缺席同学就说“我们组全体赞成”。请依据材料区分事实与未经核实的表态，提出既能推进活动又尊重参与的两步建议。','open_response','{"task_points": ["指出没有征求两名同学意见，不能宣称全体赞成。", "联系题给先征求再表决的程序与尊重参与，不臆测缺席者一定反对。", "提出补充征求并如实记录意见、按约定表决等可执行步骤。"], "review_profile": "school_open_civics_civic_argument_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "civic_argument", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先区分不知道意见与意见相反。可以联系缺席同学、说明方案并记录回应，再按规则表决；若暂时联系不上，应如实标记而非代替表态。这里依据的是题给协商规则，不是对现实纠纷作法律裁决。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-civics-facts','node-j3-civics-material','自编材料：班级规定借走共用剪刀要登记。有人看到剪刀不见，就在群里说“最后离开的小周偷走了”。登记本尚未查看，小周也未被询问。请指出现有证据能说明什么、不能说明什么，并建议怎样处理。','open_response','{"task_points": ["目前只能说剪刀未在原处或待查，不能凭最后离开认定偷走。", "建议查登记、询问相关同学、寻找物品，区分核查与公开指责。", "建议停止传播未经核实的指责，若已误传应澄清；不作有罪推断。"], "review_profile": "school_open_civics_civic_argument_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "civic_argument", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','把“看到的事”与“推测的原因”列开。先查借用登记并询问，不给同学贴标签；若公开信息有误要更正。可追问还有哪些可能原因，练习有依据地判断而不是猜测动机。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-history-sequence','node-j3-history-causality','以下是练习用的虚构历史材料，不是真实史事：某城多年运输不便；一次洪水冲断旧桥后，议事会决定建新桥；新桥建成后商队通行次数增加。请区分长期背景、直接促发因素、决策和后续变化，并说明仅凭这段材料能否断定居民收入都提高了。','open_response','{"task_points": ["多年运输不便是背景，洪水断桥是直接促发因素，建桥是决策。", "商队通行增加是材料记载的后续变化，不与背景混淆。", "没有居民收入资料，不能断定人人增收；时序也不单独证明所有因果。"], "review_profile": "school_open_history_historical_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "historical_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','按发生前、触发时、采取行动、随后四栏归类。直接记载的是通行变化，没有每位居民收入。引导孩子说明证据还缺哪一类，而不是补一个听起来合理的结论。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-j3-history-explanations','node-j3-history-causality','自编虚构历史材料：一地多年税收不足，同时有多年关于改税的讨论；某年灾害使收入骤减，官员随即提出新方案。甲说“改革只因灾害”，乙说“灾害与改革无关”。请比较两种说法的问题，并指出还需什么资料检验新方案的影响。','open_response','{"task_points": ["长期财政困难和讨论是背景，灾害可以是促发因素，不能只保留其中一层。", "材料有时间联系，但不能夸大成唯一原因，也不能武断排除灾害。", "应查实施情况、前后收支及其他变化等资料，不能把提出方案等同于改革成功。"], "review_profile": "school_open_history_historical_explanation_v1", "profile_version": "school_open_response_profiles_v1", "task_family": "historical_explanation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','分别圈出多年和随即，讨论不同层次的原因。再问“提了方案等于执行了吗”。检验影响需要实施和结果资料，不能从提案直接推断成功。',NULL,NULL,'open_response_rubric',2,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-math-grouping','node-p4-open-math-reasoning','有4盒彩笔，每盒12支，送给两个小组各9支。小青列式4×12-9，小明列式4×12-2×9。请口头判断谁的算式符合题意，解释每一部分，再算剩余支数。','open_response','{"task_points": ["4×12表示原有48支，两个小组各9支共送出18支。", "选择4×12-2×9并解释为什么不能只减9。", "剩30支，单位正确，可用30+18=48核对。"], "review_profile": "school_p4_open_math_mathematical_process_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "mathematical_process", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先问送给几个小组、每组多少。用两组各9支帮助区分一个9与两个9。48-18=30支，可用剩余加送出核对总数。给出提示后的回答只说明在帮助下理解。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-math-constraint','node-p4-open-math-reasoning','买3本同样的练习本付出20元，找回2元。小雨算20÷3，认为每本约6元多。请说明哪里漏用了条件，算出每本价格并检查。','open_response','{"task_points": ["20元是付出的钱，不是实际花费；需要先减找回的2元。", "实际18元，18÷3=6元一本。", "用3×6+2=20或等价关系核对，区分总价和单价。"], "review_profile": "school_p4_open_math_mathematical_process_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "mathematical_process", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','让孩子把付出、花掉、找回分别说清。买本子共花18元，再平均分到3本。核对时把花费与找回的钱合起来，而不是用近似结果掩盖漏掉条件。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-chinese-action','node-p4-open-chinese-reading','读自编短文：“放学时，雨越下越大。小禾走到门口，又折回教室，把窗台上还没干的画搬到书架上，才撑开伞。”小禾为什么折回？哪两个细节帮助你理解？','open_response','{"task_points": ["联系雨越下越大与窗台上未干的画，理解保护画的意图。", "依据折回、搬到书架等实际动作，不编造老师布置。", "用连贯的话连接细节与理由，允许有依据的不同说法。"], "review_profile": "school_p4_open_chinese_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','先找小禾做了什么，再看当时的天气和画的位置。她把画搬到书架，可以避免窗边的雨打湿画。文中没有说老师命令她，不需要补写。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-chinese-main','node-p4-open-chinese-reading','读自编短文：“小凯第一次折纸船，船底歪了。他拆开对齐折痕，再试一次。第二只放入水盆，稳稳浮着。”小亮说这段话主要讲水盆很大。你同意吗？请用文中事情说明主要写什么。','open_response','{"task_points": ["指出水盆很大在文中没有依据，也不是主要事件。", "按第一次失败、调整折痕、第二次成功概括。", "可以理解为调整方法继续尝试，但不把一次成功说成从不失败。"], "review_profile": "school_p4_open_chinese_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','让孩子找前后发生变化的对象，是纸船的折法和结果，不是水盆。用“先……接着……最后……”概括，再说尝试和调整的作用。',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-english-location','node-p4-open-english-reading','Read this original note: "Ben, your cap is not in the bag. It is on the chair next to the door. Please bring it to the park. Mum." Where is the cap now, and what should Ben do? Explain using the note.','open_response','{"task_points": ["帽子现在在门旁的椅子上，而不是包里或公园。", "Ben应把帽子带到公园，区分现在的位置与目的地。", "回答对应原文，不要求逐字背诵，理解与英语表达错误分别看待。"], "review_profile": "school_p4_open_english_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','Ask “Where is it now?” before “Where should it go?”. The chair is the current location; the park is the destination. Let the child point out the words supporting each answer, using Chinese to clarify meaning if needed.',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('diag-authored-oral-v1-p4-english-reason','node-p4-open-english-reading','Read this original story: "Lily takes two cups to the garden. Her little brother has no cup, so she gives one to him. They drink water together." Why does Lily give a cup to her brother? Does the story say she gives him both cups?','open_response','{"task_points": ["因为弟弟没有杯子，引用has no cup的意思。", "只给一个，不是两个；依据gives one。", "联系两人一起喝水理解行为，不补造弟弟生病等原因。"], "review_profile": "school_p4_open_english_textual_interpretation_v1", "profile_version": "school_primary_open_response_profiles_v1", "task_family": "textual_interpretation", "response_mode": "spoken_explanation", "context_requirement": "self_contained"}','Find the reason after brother and check the number after gives. She gives one because he has no cup. Keep the explanation tied to this short story; do not require a memorised moral.',NULL,NULL,'open_response_rubric',1,'hsc_original_v1','active');
INSERT INTO "diagnostic_item" VALUES('specialized-9fdd8259-951a-4a28-b48e-cdc86c547ddb','node-j3-math-discriminant','不直接求根，分析 x²+2x+5=0 在实数范围内的解的情况，并写出判别依据和推理过程。','open_response','{"context_requirement": "self_contained", "profile_version": "school_open_response_profiles_v1", "response_mode": "written", "review_profile": "school_open_math_mathematical_process_v1", "task_family": "mathematical_process", "task_points": ["说明题中条件和所用关系", "用明确的过程支持结论，并说明其适用边界"]}','仅审核原始任务和参考标准，不能按关键词或字数认证掌握。',NULL,NULL,'open_response_rubric',2,'parent_approved_specialized:9fdd8259-951a-4a28-b48e-cdc86c547ddb','active');
