INSERT INTO "specialized_supply_candidate" VALUES('9fdd8259-951a-4a28-b48e-cdc86c547ddb','a66d34d9-985c-483e-8831-3fab65a32eb4','child-junior-3','junior_exam','数学','junior_exam.数学.方程与不等式','diag-j3-discriminant-1','parallel','不直接求根，分析 x²+2x+5=0 在实数范围内的解的情况，并写出判别依据和推理过程。','{"context_requirement": "self_contained", "profile_version": "school_open_response_profiles_v1", "response_mode": "written", "review_profile": "school_open_math_mathematical_process_v1", "task_family": "mathematical_process", "task_points": ["说明题中条件和所用关系", "用明确的过程支持结论，并说明其适用边界"]}','仅审核原始任务和参考标准，不能按关键词或字数认证掌握。',2,'d729012f82ef963a4d2bd0d2fc1248c2e0a774a9950bf965863bbd83f956d296','{"passed": true, "ruleset": "curriculum_review_v1"}','promoted','specialized-9fdd8259-951a-4a28-b48e-cdc86c547ddb','2026-10-21T01:00:46.957118+00:00','curriculum independent check and review','curriculum-publish:9fdd8259-951a-4a28-b48e-cdc86c547ddb','2026-10-21T01:00:46.924495+00:00');
